// ── Merge Sort — O(n log n) time, O(n) space ──────────────────────────
// Divide: split at midpoint.
// Conquer: recursively sort each half.
// Combine: merge two sorted halves in O(n) with two pointers.

function mergeSort(arr) {
  // Base case: arrays of 0 or 1 element are already sorted
  if (arr.length <= 1) return arr;

  const mid   = Math.floor(arr.length / 2);
  const left  = mergeSort(arr.slice(0, mid));  // conquer left half
  const right = mergeSort(arr.slice(mid));      // conquer right half
  return merge(left, right);                    // combine
}

function merge(left, right) {
  const result = [];
  let i = 0, j = 0;
  // Two-pointer merge: always take the smaller front element
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i++]);   // stable: <= keeps left before right for equals
    } else {
      result.push(right[j++]);
    }
  }
  // One array is exhausted; append the rest of the other
  return result.concat(left.slice(i)).concat(right.slice(j));
}

console.log(mergeSort([5, 2, 8, 1, 9, 3]));   // [1, 2, 3, 5, 8, 9]
console.log(mergeSort([1]));                    // [1]  — base case
console.log(mergeSort([]));                     // []   — base case
console.log(mergeSort([3, 3, 1, 2, 1]));       // [1, 1, 2, 3, 3] — stable

// ── Trace the merge steps for [5, 2, 8, 1] ───────────────────────────
// Level 2:  mergeSort([5,2]) and mergeSort([8,1]) run in parallel
//   mergeSort([5,2]):
//     mergeSort([5]) → [5]
//     mergeSort([2]) → [2]
//     merge([5],[2]) → compare 5 vs 2: take 2, then 5 → [2, 5]
//   mergeSort([8,1]):
//     mergeSort([8]) → [8]
//     mergeSort([1]) → [1]
//     merge([8],[1]) → compare 8 vs 1: take 1, then 8 → [1, 8]
// Level 1:  merge([2,5],[1,8])
//   compare 2 vs 1: take 1
//   compare 2 vs 8: take 2
//   compare 5 vs 8: take 5
//   right exhausted, append [8]
//   result: [1, 2, 5, 8]

// ── Quickselect — expected O(n) k-th smallest (0-indexed) ────────────
// Partition around a random pivot, recurse on ONE side only.

function quickselect(arr, k) {
  if (arr.length === 1) return arr[0];  // base case

  // Random pivot selection avoids O(n²) worst-case
  const pivotIdx = Math.floor(Math.random() * arr.length);
  const pivot    = arr[pivotIdx];

  const less    = arr.filter(x => x <  pivot);
  const equal   = arr.filter(x => x === pivot);
  const greater = arr.filter(x => x >  pivot);

  if (k < less.length) {
    // k-th smallest is in the less partition — recurse with same k
    return quickselect(less, k);
  } else if (k < less.length + equal.length) {
    // k falls within the equal block — pivot is the answer
    return pivot;
  } else {
    // k-th smallest is in the greater partition — adjust k
    return quickselect(greater, k - less.length - equal.length);
  }
}

const data = [7, 2, 10, 4, 3, 8, 1, 9, 5, 6];
console.log(quickselect(data, 0)); // 1   — minimum (0-indexed)
console.log(quickselect(data, 4)); // 5   — median of 10 elements
console.log(quickselect(data, 9)); // 10  — maximum

// Comparison: quicksort BOTH sides vs quickselect ONE side
// quicksort:   T(n) = 2T(n/2) + O(n)  → O(n log n)  [recurse on both]
// quickselect: T(n) = T(n/2)  + O(n)  → O(n)         [recurse on one]

// Geometric series intuition for quickselect O(n):
// Level 0: partition n elements     → cost n
// Level 1: partition ~n/2 elements  → cost n/2
// Level 2: partition ~n/4 elements  → cost n/4
// ...sum = n + n/2 + n/4 + ... = 2n = O(n)

// ── Count Inversions — O(n log n) by augmenting merge sort ───────────
// An inversion: pair (i,j) where i<j but arr[i] > arr[j].
// Inversions = measure of 'how unsorted' the array is.

function countInversions(arr) {
  if (arr.length <= 1) return { sorted: arr, inversions: 0 };

  const mid = Math.floor(arr.length / 2);
  const { sorted: left,  inversions: leftInv  } = countInversions(arr.slice(0, mid));
  const { sorted: right, inversions: rightInv } = countInversions(arr.slice(mid));
  const { sorted, inversions: splitInv } = mergeAndCount(left, right);

  return { sorted, inversions: leftInv + rightInv + splitInv };
}

function mergeAndCount(left, right) {
  const result = [];
  let i = 0, j = 0, inversions = 0;

  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i++]);         // no inversion: left element is smaller
    } else {
      // right[j] < left[i], and since left is sorted,
      // right[j] is also less than left[i+1]...left[end]
      // Each of those is an inversion — count them all at once!
      inversions += left.length - i;
      result.push(right[j++]);
    }
  }

  return {
    sorted: result.concat(left.slice(i)).concat(right.slice(j)),
    inversions
  };
}

// Test cases
console.log(countInversions([1, 2, 3, 4]).inversions);     // 0  — sorted
console.log(countInversions([4, 3, 2, 1]).inversions);     // 6  — reverse sorted
console.log(countInversions([2, 4, 1, 3, 5]).inversions);  // 3  — (2,1),(4,1),(4,3)

// Verification for [2,4,1,3,5]:
